import traceback

def make():
    return OSError("boom")

def demo():
    captured = None
    try:
        e = make(); captured = e; raise e
    except OSError as retry:
        captured = retry
    # re-raise later with a cause, outside the except block
    cause = RuntimeError("cause")
    raise captured from cause

try:
    demo()
except OSError as caught:
    print("tb is None?", caught.__traceback__ is None)
    traceback.print_exception(type(caught), caught, caught.__traceback__)
